def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_c = sum(1 for x in op if x == 'C')
    opp_rate = opp_c / n
    my_c = sum(1 for x in me if x == 'C')
    my_d = n - my_c
    last_me, last_op = history[-1]

    ret_count = 0
    no_ret_count = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'D':
                ret_count += 1
            else:
                no_ret_count += 1

    recent_len = min(10, n)
    recent_op = op[-recent_len:]
    recent_opp_c = sum(1 for x in recent_op if x == 'C')
    recent_opp_d = recent_len - recent_opp_c

    if opp_rate < 0.2:
        return 'D'

    if last_op == 'D':
        if last_me == 'D':
            return 'C' if rng.random() < 0.7 else 'D'
        else:
            if my_d > 0 and opp_rate > 0.8 and recent_opp_d <= 1:
                return 'C'
            return 'D'

    if opp_rate > 0.8 and ret_count == 0 and no_ret_count > 0:
        return 'D'

    if opp_rate > 0.8 and ret_count == 0 and no_ret_count == 0:
        if last_me == 'D':
            return 'C'
        if n >= 5 and n < 95:
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    if opp_rate > 0.8:
        return 'C'

    if ret_count > no_ret_count:
        return 'C'
    else:
        if opp_rate > 0.6:
            return 'D' if rng.random() < 0.7 else 'C'
        else:
            return 'D' if rng.random() < 0.6 else 'C'
